func testTabelaNomeToManyAddOpTBNTabelaNomesCampos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a TabelaNome
	var b, c, d, e TabelaNomesCampo

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, tabelaNomeDBTypes, false, strmangle.SetComplement(tabelaNomePrimaryKeyColumns, tabelaNomeColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*TabelaNomesCampo{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, tabelaNomesCampoDBTypes, false, strmangle.SetComplement(tabelaNomesCampoPrimaryKeyColumns, tabelaNomesCampoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*TabelaNomesCampo{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddTBNTabelaNomesCampos(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.TBNID != first.TBNID {
			t.Error("foreign key was wrong value", a.TBNID, first.TBNID)
		}
		if a.TBNID != second.TBNID {
			t.Error("foreign key was wrong value", a.TBNID, second.TBNID)
		}

		if first.R.TBN != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.TBN != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.TBNTabelaNomesCampos[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.TBNTabelaNomesCampos[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.TBNTabelaNomesCampos().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

